mapper.select:
SELECT DISTINCT t.TRIP_ID, t.USER_ID, t.TRIP_NAME, t.START_DATE, t.END_DATE, t.IS_AI_ROUTE, t.SHARE_CODE, t.CREATED_AT, t.UPDATED_AT FROM TRIP t
INNER JOIN TRIP_DETAIL d ON t.TRIP_ID = d.TRIP_ID
ORDER BY t.CREATED_AT DESC LIMIT #{offset}, #{numOfRows}

mapper.insert:
INSERT INTO TRIP (
USER_ID, TRIP_NAME, START_DATE, END_DATE, IS_AI_ROUTE, SHARE_CODE
) VALUES (
#{userId}, #{tripName}, #{startDate}, #{endDate}, #{isAiRoute}, #{shareCode}
)

INSERT INTO TRIP_DETAIL (
TRIP_ID, CONTENT_ID, CONTENT_TYPE_ID, SPOT_NAME, CATEGORY,
ADDRESS, SIGUNGU_CD, LATITUDE, LONGITUDE, VISIT_TIME,
VISIT_DATE, ESTIMATED_STAY, THUMNAIL
) VALUES (
#{tripId}, #{contentId}, #{contentTypeId}, #{spotName}, #{category},
#{address}, #{sigunguCd}, #{latitude}, #{longitude}, #{visitTime},
#{visitDate}, #{estimatedStay}, #{thumnail}
)
